  "'de sıfırlanır. Kazanç tavanı Toto ile ortaktır.": ". Il tetto delle vincite è condiviso con il Toto.",
  "güncel sezon maaşı ÷ 4": "stipendio stagionale attuale ÷ 4",
  "ve talep ettiğin": "e quanto richiesto",
  "(final galibi) ayrıca": "(il vincitore della finale) inoltre",
  "de buluşur. Final hariç tüm turlar çift maçlıdır.": "si incontrano. Tutti i turni tranne la finale sono ad andata e ritorno.",
  ". Lig sonunda hak kazanan takımlar turnuvalara katılır.": ". Le squadre qualificate a fine campionato partecipano ai tornei.",
  "olarak katılacaksın. İstediğin zaman ayrılabilirsin.": "sarà il tuo ruolo. Puoi andartene quando vuoi.",
  ". Diğer üyeler oylarını veriyor.": ". Gli altri membri stanno votando.",
  ". Sonraki seçimde tekrar başvurabilirsin.": ". Potrai candidarti di nuovo alle prossime elezioni.",
  "Karşı takım kaptanı kabul ederse maç planlanır.": "La partita viene programmata se il capitano avversario accetta.",
  "(Sahadan çıkarmak için diziliş ekranında yedeğe sürükleyin.)": "(Per togliere un giocatore dal campo, trascinalo in panchina nella schermata formazione.)",
  ". Tüm takımlar, oyuncular ve maçlar kurgusaldır.": ". Tutte le squadre, i giocatori e le partite sono immaginari.",
  ". Katılım yalnızca oyun içi sanal para ile yapılır;": ". La partecipazione avviene solo con valuta virtuale di gioco;",
  ", kazanılan ödüller yalnızca oyun içinde kullanılır ve": ", i premi vinti sono utilizzabili solo nel gioco e",
  ", oyuncunun yeteneklerinin ortalamasıdır ve": ", è la media delle abilità del giocatore e",
