  "Toplam Kupa ›": "Trofei totali ›",
  "belirlenir: oyuncunun güncel yetenek seviyesine göre hesaplanır, oyuncu geliştikçe maaşı artar. Her maaş gününde": "vengono stabiliti: si calcolano in base all’attuale livello di abilità del giocatore, quindi lo stipendio cresce man mano che il giocatore migliora. A ogni giorno di paga",
  "değiştirebilir. Sen sadece görüntülüyorsun.": "possono modificarle. Tu puoi solo guardare.",
  "eklenir. Transferler ve oyuncu maaşları finanstan ödenir. Bağış yaparak finansa kişisel destek verebilirsin.": "vengono aggiunti. Trasferimenti e stipendi dei giocatori sono pagati dalle finanze. Puoi sostenere personalmente le finanze con una donazione.",
  "‹ Geri": "‹ Indietro",
