  "Antrenman süresi uzadıkça kazanım artar, ama daha çok enerji ve süre ister.": "Sessioni più lunghe danno più progressi, ma richiedono più energia e tempo.",
  "Düzenli antrenman, takımdaki yerini ve transfer değerini yükseltmenin en hızlı yoludur.": "Allenarsi con costanza è il modo più rapido per guadagnare posto in rosa e valore di mercato.",
  "Enerji sunucu saatiyle (UTC 00:00) yenilenir. Bu, her ülkede aşağıdaki yerel saate denk gelir:": "L’energia si ricarica secondo l’ora del server (UTC 00:00), che corrisponde a questo orario locale in ogni Paese:",
