  "Sezon 1 görev süresi": "Mandato stagione 1",
  "vardır. Her rolün milli takım üzerinde farklı yetkileri vardır.": ". Ogni ruolo ha poteri diversi sulla Nazionale.",
  "ANTRENMAN YILDIZI": "STELLA DELL’ALLENAMENTO",
  "🏆 Pro görevler oyunun en büyük zaferleri — şampiyonluklar ve milli takım. Tek seferlik, kalıcı.": "🏆 Le missioni Pro sono le imprese più grandi del gioco — titoli e Nazionale. Una tantum e permanenti.",
