  "🤝 Hazırlık": "🤝 Amichevole",
  "Bu işlem geri alınamaz. Gönderi ve tüm beğeni bilgileri kalıcı olarak silinecek.": "L’operazione è irreversibile. Il post e tutti i suoi like verranno eliminati definitivamente.",
