  "🏟️ Satıştaki takımları gör ve satın al. Listings kullanıcı ve botların ilanlarından oluşur.": "🏟️ Sfoglia e acquista le squadre in vendita. Gli annunci provengono sia da utenti che da bot.",
  "🏟️ Takımlar": "🏟️ Squadre",
  "💡 Diamond ile oyuncu transfer eder, tesis yükseltir, item ve takım satın alabilirsin. Büyük paketler kademeli bonus kazandırır.": "💡 Con i diamanti puoi ingaggiare giocatori, potenziare strutture e comprare oggetti o squadre. I pacchetti più grandi danno bonus crescenti.",
  "2 sezon": "2 stagioni",
  "Aynısını tekrar yaz": "Ripeti la password",
  "Beceri puanı maç motoruna ±%5 etki eder. Uzmanlık alanı belirli istatistiklere bonus verir.": "I punti abilità influenzano il motore partita del ±5%. Una specializzazione dà un bonus a certe statistiche.",
  "Bonservis ve maaş sistemce belirlenmiştir. Maaş sezonun 10., 20., 30. ve 40. günlerinde 4 taksit halinde takım kasasından oyuncu cüzdanına ödenir.": "Costo del cartellino e stipendio sono fissati dal sistema. Lo stipendio viene pagato dalla cassa della squadra al portafoglio del giocatore in 4 rate, nei giorni 10, 20, 30 e 40 della stagione.",
  "Bu oyuncu zaten kadronda": "Questo giocatore è già nella tua rosa",
  "Daha Sonra": "Più tardi",
  "Hesabın için yeni bir şifre yaz.": "Scegli una nuova password per il tuo account.",
  "Hesabını silmek kalıcıdır. Takımın, oyuncun, cüzdanın ve tüm ilerlemen geri alınamaz şekilde kaldırılır.": "L’eliminazione dell’account è definitiva. Squadra, giocatore, portafoglio e tutti i progressi verranno rimossi in modo irreversibile.",
  "Opsiyonel. Onay verildiği an oyuncunun elmas cüzdanına aktarılır. Kasa elması (€ değil) kullanılır.": "Facoltativo. Trasferito al portafoglio diamanti del giocatore al momento dell’approvazione. Si usano i diamanti della cassa (non €).",
  "Oyuncu Transfer › Boştaki Oyuncular kısmına eklenecek. Yerine yeni bir oyuncu gelecek.": "Il giocatore verrà aggiunto a Trasferimenti › Svincolati. Al suo posto arriverà un nuovo giocatore.",
  "Oyuncu seviyesine göre hesaplandı (40 günlük antrenman maliyeti × 1,045).": "Calcolato in base al livello del giocatore (costo di 40 giorni di allenamento × 1,045).",
  "Oyuncunun mevcut piyasa değeri. Onay verildiği an satıcı kasasına aktarılır.": "L’attuale valore di mercato del giocatore. Trasferito alla cassa del venditore al momento dell’approvazione.",
