  "💡 Hazırlık maçları lig fikstürüne dahil değildir. Sadece bilgi amaçlı listelenir.": "💡 Le amichevoli non fanno parte del calendario del campionato. Sono elencate solo a titolo informativo.",
  "💡 Senin ve rakip takımın gerçek lig maçlarına en az": "💡 Distanza minima dalle partite ufficiali tue e dell'avversario:",
  "💡 Serbest oyuncular bu kuraldan etkilenmez — her zaman katılabilir.": "💡 Gli svincolati non sono soggetti a questa regola — possono sempre entrare.",
  "💡 Şartları karşılayan oyuncular onaysız direkt katılır. Karşılamayanlar onay isteğini gönderir, sen veya yardımcı kaptanlar onaylar.": "💡 I giocatori che soddisfano i requisiti entrano subito senza approvazione. Gli altri inviano una richiesta che approvi tu o i tuoi vice.",
  "gün ileri tarihe hazırlık maçı ayarlayabilirsin.": "giorni, per poter fissare un'amichevole.",
  "Bu gün için zaten bir hazırlık maçın var (": "Hai già un'amichevole in questo giorno (",
  "). Günde en fazla 1 hazırlık maçı yapılabilir.": "). Massimo 1 amichevole al giorno.",
  "). Tesisleri yükselt veya bir oyuncu kov.": "). Migliora le strutture o svincola un giocatore.",
  "). 32 milli takım 8 gruba ayrılacak. Eşleşmeler kura sonrası burada görünecek.": "). 32 nazionali saranno divise in 8 gironi. Gli accoppiamenti appariranno qui dopo il sorteggio.",
  "'de takvimimiz uygun değil. Başka bir zaman tekrar deneyebilirsin.": "il nostro calendario non lo permette. Puoi riprovare un'altra volta.",
  "'deki hazırlık maçı teklifini kabul ediyoruz. Hazırız!": "accettiamo la tua proposta di amichevole. Siamo pronti!",
  "Davet için teşekkürler ama o tarihte hazırlık programımız dolu. Bir dahaki sefere.": "Grazie per l'invito, ma in quella data il nostro programma è pieno. Alla prossima.",
  "olarak şu an hazırlık maçı için müsait değiliz.": "al momento non siamo disponibili per un'amichevole.",
  ": Çeviri yakında! Şimdilik Türkçe kullanılıyor.": ": Traduzione in arrivo! Per ora si usa il turco.",
  "Backend bağlandığında dünya üzerindeki kullanıcıların paylaşımları burada gözükecek.": "Quando il backend sarà collegato, qui appariranno i post degli utenti di tutto il mondo.",
  "Backend bağlandığında takip ettiğin kullanıcıların paylaşımları burada gözükecek.": "Quando il backend sarà collegato, qui appariranno i post degli utenti che segui.",
  "Backend bağlandığında ülkendeki kullanıcıların paylaşımları burada gözükecek.": "Quando il backend sarà collegato, qui appariranno i post degli utenti del tuo paese.",
  "Hesabını tanımak ve ilerlemeni cihazlar arası korumak": "Identificare il tuo account e conservare i progressi tra dispositivi",
  "Diğer oyuncularla etkileşimi (takım, transfer, sohbet) sağlamak": "Consentire l'interazione con altri giocatori (squadre, trasferimenti, chat)",
  "Maçları simüle etmek, lig ve turnuvaları yürütmek": "Simulare le partite e gestire campionati e tornei",
  "Konum, kişi listesi, kamera, mikrofon veya reklam kimliği": "Posizione, contatti, fotocamera, microfono o ID pubblicitario",
  "e-posta adresi, kullanıcı adı, oyuncu adı, uyruk ve yaş aralığı.": "indirizzo e-mail, nome utente, nome del giocatore, nazionalità e fascia d'età.",
  "e-posta adresin, cüzdan hareketlerin, gelen kutun, ekipmandan gelen bonus ayrıntıların.": "il tuo indirizzo e-mail, i movimenti del portafoglio, la posta in arrivo e i dettagli dei bonus dell'equipaggiamento.",
  "oyuncu adın, takımın, yetenek toplamların, maç istatistiklerin, paylaşımların.": "il nome del tuo giocatore, la squadra, i totali delle abilità, le statistiche delle partite e i post.",
  "takım sohbeti, CSC Media paylaşımları, gelen kutusu mesajları, federasyon oyları.": "chat di squadra, post su CSC Media, messaggi della posta in arrivo e voti della federazione.",
  "Veriler Supabase (PostgreSQL) altyapısında, şifreli bağlantı üzerinden saklanır. Şifreler tek yönlü olarak saklanır; hiç kimse ham şifreni göremez.": "I dati sono conservati su Supabase (PostgreSQL) tramite connessione cifrata. Le password sono salvate in modo irreversibile; nessuno può vedere la tua password in chiaro.",
  "Hesabın aktif olduğu sürece. Hesabını sildiğinde kişisel verilerin kalıcı olarak kaldırılır (bkz. madde 7).": "Finché il tuo account è attivo. Quando elimini l'account, i tuoi dati personali vengono rimossi definitivamente (vedi punto 7).",
  "hangi verilerin tutulduğunu talep edebilirsin.": "puoi chiedere quali dati sono conservati.",
  "İstediğin zaman Ayarlar → Hesabımı Sil ile hesabını kalıcı olarak silebilirsin.": "Puoi eliminare definitivamente il tuo account in qualsiasi momento da Impostazioni → Elimina il mio account.",
  "Ayarlar → Hesabımı Sil ile tüm verini kalıcı silebilirsin.": "Puoi eliminare definitivamente tutti i tuoi dati da Impostazioni → Elimina il mio account.",
  "profil bilgilerini uygulama içinden değiştirebilirsin.": "puoi modificare i dati del profilo all'interno dell'app.",
  "Oyun 13 yaşın altındaki kullanıcılara yönelik değildir. Bilerek 13 yaş altından veri toplamayız.": "Il gioco non è destinato a utenti sotto i 13 anni. Non raccogliamo consapevolmente dati di minori di 13 anni.",
  "Başkasının hesabını kullanmak veya hesap alışverişi yasaktır.": "È vietato usare l'account di un'altra persona o scambiare account.",
  "Hile, otomasyon (bot), açık kötüye kullanımı yasaktır.": "Sono vietati trucchi, automazioni (bot) e sfruttamento di bug.",
  "Hakaret, taciz, nefret söylemi ve spam yasaktır.": "Sono vietati insulti, molestie, incitamento all'odio e spam.",
  "Kural ihlalinde hesap askıya alınabilir veya kapatılabilir.": "La violazione delle regole può comportare la sospensione o la chiusura dell'account.",
  "Paylaştığın metinlerden sen sorumlusun. Kurallara aykırı içerik uyarı yapılmadan kaldırılabilir.": "Sei responsabile dei testi che pubblichi. I contenuti contrari alle regole possono essere rimossi senza preavviso.",
  "Oyun geliştirme aşamasındadır. Özellikler değişebilir, denge ayarları yapılabilir; bakım nedeniyle geçici kesintiler olabilir.": "Il gioco è in fase di sviluppo. Le funzioni possono cambiare, il bilanciamento può essere modificato e possono verificarsi interruzioni temporanee per manutenzione.",
  "Oyun \"olduğu gibi\" sunulur. Veri kaybı veya kesintilerden doğan dolaylı zararlardan sorumluluk kabul edilmez.": "Il gioco è fornito \"così com'è\". Non si accetta alcuna responsabilità per danni indiretti derivanti da perdita di dati o interruzioni.",
  "yalnızca oyun içinde geçerli sanal değerlerdir. Gerçek para karşılığı değildir, nakde çevrilemez, oyun dışına aktarılamaz ve gerçek bir değer taşımaz.": "sono valori virtuali validi solo all'interno del gioco. Non sono denaro reale, non possono essere convertiti in contanti né trasferiti fuori dal gioco e non hanno alcun valore reale.",
  "Sorular için Ayarlar → Talep İlet üzerinden yöneticiye ulaşabilirsin.": "Per domande puoi contattare l'amministratore da Impostazioni → Invia una richiesta.",
  "⬇️ Bir alt lige düştün. Toparlanma vakti.": "⬇️ Sei retrocesso. È ora di ripartire.",
  "'de iyi bir maç çıkaralım.": "facciamo una bella partita.",
  "'de kura çekilecek.": "si terrà il sorteggio.",
  "'de sahada görüşürüz.": "ci vediamo in campo.",
