  "Bu genelde birkaç dakika içinde kendiliğinden düzelir — mağaza sayfasını": "Di solito si risolve da solo entro pochi minuti — la pagina del negozio",
  "Hesap oluşturuldu ama oyuncu kaydın hazırlanamadı. Birkaç saniye sonra": "L'account è stato creato ma il tuo profilo giocatore non è stato preparato. Tra qualche secondo",
