  "3-6. Sıra: Elenir (alt turnuva yok)": "3º-6º posto: eliminati (nessun torneo inferiore)",
  "8 grubun 1. ve 2.'leri Son 16'ya yükselir (16 takım). Final hariç tüm turlar çift maçlıdır (ev+deplasman, toplam skor).": "Le prime 2 degli 8 gironi passano agli ottavi di finale (16 squadre). Tutti i turni tranne la finale sono di andata e ritorno (casa e trasferta, punteggio totale).",
  "8 grubun ilk 2'si Son 16'ya yükselir. Her tur tek maç eleme (berabere durumunda penaltı).": "Le prime 2 degli 8 gironi passano agli ottavi di finale. Ogni turno è a eliminazione diretta in gara unica (rigori in caso di pareggio).",
  "CON grupların 1-2'leri (16) + ELI gruplarının 3-4'leri (16) = 32 takım Son 32'de buluşur. Final hariç tüm turlar çift maçlıdır.": "Le prime 2 dei gironi CON (16) + le 3ª e 4ª dei gironi ELI (16) = 32 squadre ai sedicesimi di finale. Tutti i turni tranne la finale sono di andata e ritorno.",
  "ELI grupların 1-2'leri (16) + CHM gruplarının 3-4'leri (16) = 32 takım Son 32'de buluşur. Final hariç tüm turlar çift maçlıdır.": "Le prime 2 dei gironi ELI (16) + le 3ª e 4ª dei gironi CHM (16) = 32 squadre ai sedicesimi di finale. Tutti i turni tranne la finale sono di andata e ritorno.",
  "Her ülkenin Süper Lig 1. ve 2. sırası (32×2=64 takım)": "1ª e 2ª della Superlega di ogni paese (32×2=64 squadre)",
  "Her ülkenin Süper Lig 1. ve 2. sırası (32×2=64 → Play-Off → 32 takım)": "1ª e 2ª della Superlega di ogni paese (32×2=64 → Play-Off → 32 squadre)",
  "Her ülkenin Süper Lig 3. ve 4. sırası (32×2=64 takım)": "3ª e 4ª della Superlega di ogni paese (32×2=64 squadre)",
  "Her ülkenin Süper Lig 3. ve 4. sırası (32×2=64 → PO1 → PO2 → 32 takım)": "3ª e 4ª della Superlega di ogni paese (32×2=64 → PO1 → PO2 → 32 squadre)",
  "Her ülkenin Süper Lig 5. ve 6. sırası (32×2=64 takım)": "5ª e 6ª della Superlega di ogni paese (32×2=64 squadre)",
  "Her ülkenin Süper Lig 5. ve 6. sırası (32×2=64 → PO1 → PO2 → 32 takım)": "5ª e 6ª della Superlega di ogni paese (32×2=64 → PO1 → PO2 → 32 squadre)",
  "Eleme turu fikstürü, grup aşaması tamamlandığında otomatik oluşturulacak.": "Il tabellone a eliminazione verrà generato automaticamente al termine della fase a gironi.",
  "Gruplarını tamamlayan takımlar elemeye yükseldi. Rakipler, üst lig grupları bittikçe eşleştirilecek.": "Le squadre che hanno completato i gironi sono passate alla fase a eliminazione. Gli avversari verranno abbinati man mano che si concludono i gironi delle divisioni superiori.",
