  "Her atış için süren. Süre dolarsa sıra rakibine geçer; üst üste 3 sırasını kaçıran maçı kaybeder.": "Il tuo tempo per ogni tiro. Se scade, il turno passa all'avversario; chi salta 3 turni di fila perde la partita.",
