  "Kabulden sonra iki oyuncu da bu sürede maça girmeli; giremeyen olursa maç iptal olur ve iki ücret de iade edilir.": "Dopo l'accettazione entrambi i giocatori devono entrare nella partita entro questo tempo; se uno non entra, la partita viene annullata ed entrambi i costi vengono rimborsati.",
