  "Galibiyet, beraberlik ve mağlubiyet puanı. Puanlar penaltı düellosu puanlarıyla birlikte haftalık Düello Ustası yarışına yazılır.": "Punti per vittoria, pareggio e sconfitta. I punti valgono, insieme a quelli del duello ai rigori, per la gara settimanale Re del duello.",
