  "Takım arkadaşınla FİSKE yalnız eğlence içindir: puan yazılmaz ve günlük hakkından düşmez. Taşlar ev ve deplasman formasıyla ayrılır.": "FİSKE con un compagno è solo per divertimento: niente punti e non conta nel limite giornaliero. Le pedine hanno la maglia di casa e quella da trasferta.",
